def compute(vars):
    unearned_revenue = vars["v1"]
    accrued_revenue = vars["v2"]
    difference = unearned_revenue - accrued_revenue

    return {
        "value": difference,
        "trace": {
            "unearned_revenue": unearned_revenue,
            "accrued_revenue": accrued_revenue,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
